import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel source for smooth L1 loss (Huber)
smooth_l1_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void smooth_l1_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float diff = a[idx] - b[idx];
        float abs_diff = fabsf(diff);
        float eps = 1e-6f;
        float loss;
        if (abs_diff <= eps) {
            loss = 0.5 * diff * diff;
        } else {
            // Huber linear region: slope = eps, offset = eps^2/3
            loss = 0.5 * eps * abs_diff + (eps * eps) / 3.0f;
        }
        out[idx] = loss;
    }
}

torch::Tensor smooth_l1_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    smooth_l1_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float()>, size);

    return out;
}
"""

# C++ source declaration for the function
smooth_l1_cpp_source = 'torch::Tensor smooth_l1_cuda(torch::Tensor a, torch::Tensor b);'

